class JSONResponse(Response):
    """Response class that knows how to decode a JSON body.

    ``get_json()`` and the ``json`` property are conveniences that only became
    part of Flask itself after the release this application is built on.
    """

    def get_json(self, force=False, silent=False, cache=True):
        if not (force or self.is_json):
            return None
        try:
            return flask_json.loads(self.get_data(as_text=True))
        except ValueError:
            if silent:
                return None
            raise

    @property
    def is_json(self):
        mimetype = self.mimetype or ''
        return mimetype == 'application/json' or \
            (mimetype.startswith('application/') and
             mimetype.endswith('+json'))

    @property
    def json(self):
        return self.get_json()


class JSONTestClient(FlaskClient):
